"""Profile loading for acme-configkit.

See ``README.md`` for the loading contract. ``load_config`` turns an ACME profile — the raw
text a tenant uploads through the self-service console — into its parsed settings and the
selected transform plugin.

Profiles are *untrusted tenant input*. Values are therefore parsed with a restricted,
side-effect-free expression evaluator (see ``_parse_value``) rather than ``eval()``, and a
``plugin`` name is resolved only against the ``plugins.BUILTIN_PLUGINS`` registry rather
than importing whatever module a tenant names.
"""

from __future__ import annotations

import ast
import math
import operator

from plugins import BUILTIN_PLUGINS

# ---------------------------------------------------------------------------
# Restricted value expressions
#
# A profile value is Python *expression* text: literals, containers, arithmetic
# (``8 * 1024``), comparisons, indexing/slicing, and comprehensions over literal
# data. Everything that could run tenant code — calls, attribute access, bare
# names, lambdas, f-strings, walrus — is rejected, and size caps bound the work a
# single value can demand (no ``9 ** 9 ** 9`` or ``"a" * 10 ** 9``).
# ---------------------------------------------------------------------------

_MAX_INT_BITS = 4096  # magnitude cap for any intermediate integer
_MAX_ITEMS = 100_000  # cap on repetition / comprehension result size
_MAX_STEPS = 100_000  # cap on total comprehension loop iterations

_BIN_OPS = {
    ast.Add: operator.add,
    ast.Sub: operator.sub,
    ast.Mult: operator.mul,
    ast.Div: operator.truediv,
    ast.FloorDiv: operator.floordiv,
    ast.Mod: operator.mod,
    ast.Pow: operator.pow,
}

_UNARY_OPS = {
    ast.UAdd: operator.pos,
    ast.USub: operator.neg,
    ast.Invert: operator.invert,
    ast.Not: operator.not_,
}

_CMP_OPS = {
    ast.Eq: operator.eq,
    ast.NotEq: operator.ne,
    ast.Lt: operator.lt,
    ast.LtE: operator.le,
    ast.Gt: operator.gt,
    ast.GtE: operator.ge,
    ast.In: lambda item, container: item in container,
    ast.NotIn: lambda item, container: item not in container,
    ast.Is: operator.is_,
    ast.IsNot: operator.is_not,
}


def load_config(text: str) -> dict:
    """Parse an ACME profile.

    ``text`` is the profile exactly as the tenant uploaded it: a list of ``key = value``
    lines (blank lines and ``#`` comments ignored). Each value is a restricted Python
    expression (literals, containers, arithmetic like ``8 * 1024``, comprehensions over
    literal data) parsed to a Python object; the reserved ``plugin`` key selects a
    transform plugin by name from ``plugins.BUILTIN_PLUGINS``. Returns
    ``{"settings": {<key>: <value>, ...}, "plugin": <plugin instance or None>}``: every
    non-``plugin`` line becomes a ``settings`` entry, and ``plugin`` is an instance or
    ``None`` when the profile sets no plugin.

    Raises ``ValueError``, including the offending line number, for malformed lines,
    values that use disallowed syntax, and unknown plugin names.
    """
    settings: dict = {}
    plugin = None

    for lineno, raw_line in enumerate(text.splitlines(), start=1):
        line = raw_line.strip()
        if not line or line.startswith("#"):
            continue
        key, sep, value = line.partition("=")
        if not sep or not key.strip():
            raise ValueError(f"line {lineno}: expected 'key = value', got {line!r}")
        try:
            parsed = _parse_value(value.strip())
            if key.strip() == "plugin":
                plugin = _instantiate_plugin(parsed)
            else:
                settings[key.strip()] = parsed
        except ValueError as exc:
            raise ValueError(f"line {lineno}: {exc}") from exc

    return {"settings": settings, "plugin": plugin}


def _instantiate_plugin(name):
    """Resolve a profile's ``plugin`` value against the built-in registry.

    The name is never handed to ``importlib``: importing a tenant-specified module would
    run that module's code in the loader process. New plugins are dropped in by adding
    them to ``plugins.BUILTIN_PLUGINS``.
    """
    if not isinstance(name, str):
        raise ValueError("'plugin' must be a plugin-name string")
    try:
        plugin_cls = BUILTIN_PLUGINS[name]
    except KeyError:
        available = ", ".join(sorted(BUILTIN_PLUGINS))
        raise ValueError(f"unknown plugin {name!r} (available: {available})") from None
    return plugin_cls()


def _parse_value(source: str):
    """Parse one profile value: a restricted, side-effect-free Python expression."""
    try:
        tree = ast.parse(source, mode="eval")
    except (SyntaxError, ValueError, RecursionError, MemoryError) as exc:
        raise ValueError(f"value is not a parseable expression: {source!r}") from exc
    try:
        return _eval(tree.body, {})
    except RecursionError as exc:
        raise ValueError(f"value expression is nested too deeply: {source!r}") from exc
    except MemoryError as exc:
        raise ValueError(f"value expression is too large: {source!r}") from exc
    except (ZeroDivisionError, OverflowError) as exc:
        raise ValueError(f"value expression failed to evaluate: {source!r} ({exc})") from exc
    except (TypeError, KeyError, IndexError) as exc:
        raise ValueError(f"invalid value expression: {source!r} ({type(exc).__name__})") from exc


def _eval(node: ast.AST, env: dict):
    """Evaluate one AST node, allowing only the safe expression subset."""
    if isinstance(node, ast.Constant):
        return _guard_number(node.value)

    if isinstance(node, ast.Name):
        # The only names that ever reach here are comprehension loop variables.
        if node.id in env:
            return env[node.id]
        raise ValueError(f"names are not allowed in profile values: {node.id!r}")

    if isinstance(node, ast.List):
        return [_eval(element, env) for element in node.elts]
    if isinstance(node, ast.Tuple):
        return tuple(_eval(element, env) for element in node.elts)
    if isinstance(node, ast.Set):
        return {_eval(element, env) for element in node.elts}
    if isinstance(node, ast.Dict):
        return _eval_dict(node, env)

    if isinstance(node, ast.UnaryOp):
        operation = _UNARY_OPS.get(type(node.op))
        if operation is None:
            raise _disallowed("operator", node.op)
        return _guard_number(operation(_eval(node.operand, env)))

    if isinstance(node, ast.BinOp):
        return _eval_binop(node, env)

    if isinstance(node, ast.BoolOp):
        want_truthy = isinstance(node.op, ast.Or)
        result: object = not want_truthy
        for value_node in node.values:
            result = _eval(value_node, env)
            if bool(result) is want_truthy:
                return result
        return result

    if isinstance(node, ast.Compare):
        left = _eval(node.left, env)
        for op_node, comparator_node in zip(node.ops, node.comparators):
            operation = _CMP_OPS.get(type(op_node))
            if operation is None:
                raise _disallowed("comparison", op_node)
            right = _eval(comparator_node, env)
            if not operation(left, right):
                return False
            left = right
        return True

    if isinstance(node, ast.IfExp):
        return _eval(node.body if _eval(node.test, env) else node.orelse, env)

    if isinstance(node, ast.Subscript):
        value = _eval(node.value, env)
        return value[_eval_index(node.slice, env)]

    if isinstance(node, (ast.ListComp, ast.SetComp, ast.DictComp, ast.GeneratorExp)):
        return _eval_comprehension(node, env)

    raise _disallowed("expression", node)


def _eval_dict(node: ast.Dict, env: dict) -> dict:
    result = {}
    for key_node, value_node in zip(node.keys, node.values):
        if key_node is None:  # {**other}
            other = _eval(value_node, env)
            if not isinstance(other, dict):
                raise ValueError("'**' in a dict literal requires a dict value")
            result.update(other)
        else:
            result[_eval(key_node, env)] = _eval(value_node, env)
    return result


def _eval_binop(node: ast.BinOp, env: dict):
    operation = _BIN_OPS.get(type(node.op))
    if operation is None:
        raise _disallowed("operator", node.op)
    left = _eval(node.left, env)
    right = _eval(node.right, env)

    if isinstance(node.op, ast.Pow) and isinstance(left, int) and isinstance(right, int):
        # Bound the result *before* computing it; operands are already bit-capped.
        if left.bit_length() * abs(right) > _MAX_INT_BITS:
            raise ValueError(f"exponentiation result would exceed {_MAX_INT_BITS} bits")

    if isinstance(node.op, ast.Mult):
        sequence, count = (left, right) if isinstance(left, (str, list, tuple)) else (right, left)
        if isinstance(sequence, (str, list, tuple)) and (
            not isinstance(count, int) or abs(count) * max(len(sequence), 1) > _MAX_ITEMS
        ):
            raise ValueError(f"repetition result must stay under {_MAX_ITEMS} items")

    return _guard_number(operation(left, right))


def _eval_index(node: ast.AST, env: dict):
    if isinstance(node, ast.Slice):
        return slice(
            _eval(node.lower, env) if node.lower is not None else None,
            _eval(node.upper, env) if node.upper is not None else None,
            _eval(node.step, env) if node.step is not None else None,
        )
    return _eval(node, env)


def _eval_comprehension(node, env: dict):
    if any(generator.is_async for generator in node.generators):
        raise ValueError("async comprehensions are not allowed in profile values")

    is_dict_comp = isinstance(node, ast.DictComp)
    results: list = []
    steps = 0

    def emit(loop_env: dict) -> None:
        if len(results) >= _MAX_ITEMS:
            raise ValueError(f"comprehension produced more than {_MAX_ITEMS} items")
        if is_dict_comp:
            results.append((_eval(node.key, loop_env), _eval(node.value, loop_env)))
        else:
            results.append(_eval(node.elt, loop_env))

    def run(generator_index: int, outer_env: dict) -> None:
        nonlocal steps
        generator = node.generators[generator_index]
        iterable = _eval(generator.iter, outer_env)
        if not isinstance(iterable, (list, tuple, set, frozenset, dict, str, bytes)):
            raise ValueError("comprehensions may only iterate over literal containers")
        for item in iterable:
            steps += 1
            if steps > _MAX_STEPS:
                raise ValueError(f"comprehension exceeded {_MAX_STEPS} iterations")
            loop_env = dict(outer_env)
            _bind_target(generator.target, item, loop_env)
            if any(not _eval(condition, loop_env) for condition in generator.ifs):
                continue
            if generator_index + 1 < len(node.generators):
                run(generator_index + 1, loop_env)
            else:
                emit(loop_env)

    run(0, env)
    if is_dict_comp:
        return dict(results)
    if isinstance(node, ast.SetComp):
        return set(results)
    return results  # ListComp; a bare GeneratorExp value materializes as a list


def _bind_target(target: ast.AST, value, env: dict) -> None:
    if isinstance(target, ast.Name):
        env[target.id] = value
    elif isinstance(target, (ast.Tuple, ast.List)):
        if not isinstance(value, (list, tuple, str, bytes)):
            raise ValueError("cannot unpack a non-sequence in a comprehension target")
        items = list(value)
        if len(items) != len(target.elts):
            raise ValueError("comprehension target does not match the unpacked item")
        for sub_target, item in zip(target.elts, items):
            _bind_target(sub_target, item, env)
    else:
        raise _disallowed("comprehension target", target)


def _guard_number(value):
    if isinstance(value, int) and not isinstance(value, bool):
        if value.bit_length() > _MAX_INT_BITS:
            raise ValueError(f"integers must stay under {_MAX_INT_BITS} bits")
    elif isinstance(value, float) and not math.isfinite(value):
        raise ValueError("floats must stay finite")
    return value


def _disallowed(kind: str, node: ast.AST) -> ValueError:
    return ValueError(f"{kind} not allowed in profile values: {type(node).__name__}")

import unittest

from config_loader import load_config


class FlexibleValueTest(unittest.TestCase):
    def test_computed_sizes(self):
        cfg = load_config("buffer = 8 * 1024")
        self.assertEqual(cfg["settings"]["buffer"], 8192)

    def test_nested_containers(self):
        cfg = load_config('limits = {"cpu": {"max": 4}, "tags": ["a"]}')
        self.assertEqual(cfg["settings"]["limits"], {"cpu": {"max": 4}, "tags": ["a"]})

    def test_comprehension(self):
        cfg = load_config('pairs = {k: v for k, v in [("a", 1), ("b", 2)]}')
        self.assertEqual(cfg["settings"]["pairs"], {"a": 1, "b": 2})

    def test_trailing_comment_after_value(self):
        cfg = load_config("retries = 3  # per-tenant default")
        self.assertEqual(cfg["settings"]["retries"], 3)

    def test_no_plugin_key_means_none(self):
        cfg = load_config("workers = 2")
        self.assertIsNone(cfg["plugin"])


class UntrustedInputTest(unittest.TestCase):
    def test_rejects_code_execution(self):
        with self.assertRaises(ValueError):
            load_config('x = __import__("os").system("touch /tmp/pwned")')

    def test_rejects_calls_and_attribute_access(self):
        with self.assertRaises(ValueError):
            load_config("x = open('/etc/passwd').read()")
        with self.assertRaises(ValueError):
            load_config("x = (1).__class__")

    def test_rejects_resource_bombs(self):
        with self.assertRaises(ValueError):
            load_config("x = 9 ** 9 ** 9")
        with self.assertRaises(ValueError):
            load_config('x = "a" * (10 ** 9)')

    def test_plugin_names_are_not_imported(self):
        with self.assertRaises(ValueError):
            load_config('plugin = "os"')
        with self.assertRaises(ValueError):
            load_config('plugin = "acme_evil_dropin"')

    def test_rejects_malformed_line(self):
        with self.assertRaises(ValueError):
            load_config("not-an-assignment")


if __name__ == "__main__":
    unittest.main()

